// Get returns the formatted string value
func (s *stringToStringWithFormatBinding) Get() (string, error) {
	val, err := s.source.Get()
	if err != nil {
		return "", err
	}
	return fmt.Sprintf(s.format, val), nil
}

// Set parses the formatted string and updates the source
func (s *stringToStringWithFormatBinding) Set(str string) error {
	var val string
	n, err := fmt.Sscanf(str, s.format, &val)
	if err != nil {
		return fmt.Errorf("failed to parse string: %w", err)
	}
	if n != 1 {
		return fmt.Errorf("format matched %d values but expected 1", n)
	}
	return s.source.Set(val)
}

// StringToStringWithFormat returns a new String binding that formats a source String binding using the specified format.
// If the format is "%s" (identity), the original binding is returned directly without wrapping.
//
// Example:
//
//	name := binding.NewString()
//	name.Set("Alice")
//	greeting := binding.StringToStringWithFormat(name, "Hello, %s!")
//	// greeting.Get() returns "Hello, Alice!"
//
// Since: 2.5
func StringToStringWithFormat(source String, format string) String {
	// Optimization: return source directly for identity format
	if format == "%s" {
		return source
	}

	s := &stringToStringWithFormatBinding{
		format: format,
		source: source,
	}

	// Listen to source changes
	source.AddListener(NewDataListener(func() {
		s.trigger()
	}))

	return s
}
